import pathlib,json,subprocess,hashlib
p=pathlib.Path('/root/storage-probe')
def save(path,data):
 path.write_text(data if isinstance(data,str) else json.dumps(data));path.chmod(0o600)
def kubectl(args):
 return subprocess.check_output(['/usr/local/bin/k3s','kubectl',*args])
def resource(args):return json.loads(kubectl([*args,'-o','json']))
ns=resource(['get','namespace','ac-kube-component']);rc=resource(['get','runtimeclass','gvisor']);np=resource(['get','networkpolicy','-n','ac-kube-component','ac-deny-all']);sc=resource(['get','storageclass','ac-juicefs']);driver=resource(['get','csidriver','csi.juicefs.com'])
mount=json.loads(pathlib.Path('/mnt/ac-juicefs/.config').read_text());uuid=mount['Format']['UUID']
config={'database_url_file':str(p/'control-url'),'observation_file':str(p/'worker-observation.json'),'kubernetes':{'api_url':'https://127.0.0.1:6443/','ca_file':str(p/'api-ca.pem'),'token_file':str(p/'api-token'),'deployment':{'namespace':'ac-kube-component','namespace_uid':ns['metadata']['uid'],'runtime_class_uid':rc['metadata']['uid'],'deny_policy_uid':np['metadata']['uid'],'network_policy_ref':'id:unused'},'storage':{'reference':'id:pending','name':'ac-juicefs','uid':sc['metadata']['uid'],'driver_uid':driver['metadata']['uid'],'secret_name':'ac-juicefs-secret','secret_namespace':'kube-system'}},'candidate':{'mount_root':'/mnt/ac-juicefs','object_cache':str(p/'objects'),'target':{'volume_id':'pending','namespace_uid':ns['metadata']['uid'],'pvc_uid':'pending','pv_uid':'pending','filesystem_uuid':uuid,'volume_path':'pending','writer_uid':1000,'writer_gid':1000},'quota':{'executable':'/usr/local/bin/juicefs','executable_sha256':'sha256:'+hashlib.file_digest(open('/usr/local/bin/juicefs','rb'),'sha256').hexdigest(),'metadata_url':'postgres://jfsmeta@10.0.2.15:5432/jfsmeta?sslmode=disable','password_file':str(p/'metadata-password'),'timeout_seconds':30}}}
save(p/'worker-config.json',config)
print('Private Candidate worker configuration created; control and metadata use separate databases and roles.')
